index 0000000000..f4daf388e6
--- /dev/null
+++ b/ui/lib/compliance/score-utils.ts
@@ -0,0 +1,55 @@
+/**
+ * Score utility functions for ThreatScore visualization.
+ * Used by threatscore-breakdown-card and threatscore-badge components.
+ */
+
+export const SCORE_THRESHOLDS = {
+  SUCCESS: 80,
+  WARNING: 40,
+} as const;
+
+export const SCORE_COLORS = {
+  DANGER: "var(--bg-fail-primary)",
+  WARNING: "var(--bg-warning-primary)",
+  SUCCESS: "var(--bg-pass-primary)",
+  NEUTRAL: "var(--bg-neutral-tertiary)",
+} as const;
+
+export const SCORE_LEVELS = {
+  SUCCESS: "SUCCESS",
+  WARNING: "WARNING",
+  DANGER: "DANGER",
+} as const;
+export type ScoreLevel = (typeof SCORE_LEVELS)[keyof typeof SCORE_LEVELS];
+
+export const SCORE_COLOR_VARIANTS = {
+  SUCCESS: "success",
+  WARNING: "warning",
+  DANGER: "danger",
+} as const;
+export type ScoreColorVariant =
+  (typeof SCORE_COLOR_VARIANTS)[keyof typeof SCORE_COLOR_VARIANTS];
+
+export function getScoreLevel(score: number): ScoreLevel {
+  if (score >= SCORE_THRESHOLDS.SUCCESS) return "SUCCESS";
+  if (score >= SCORE_THRESHOLDS.WARNING) return "WARNING";
+  return "DANGER";
+}
+
+export function getScoreColor(score: number): ScoreColorVariant {
+  if (score >= SCORE_THRESHOLDS.SUCCESS) return "success";
+  if (score >= SCORE_THRESHOLDS.WARNING) return "warning";
+  return "danger";
+}
+
+export function getScoreTextClass(score: number): string {
+  if (score >= SCORE_THRESHOLDS.SUCCESS) return "text-success";
+  if (score >= SCORE_THRESHOLDS.WARNING) return "text-warning";
+  return "text-danger";
+}
+
+export function getScoreLabel(score: number): string {
+  if (score >= SCORE_THRESHOLDS.SUCCESS) return "Secure";
+  if (score >= SCORE_THRESHOLDS.WARNING) return "Moderate Risk";
+  return "Critical Risk";
+}

human_review_comments.body:
![critical](https://www.gstatic.com/codereviewagent/critical.svg)

The current implementation using `ProcessPoolExecutor` will raise a `ValueError` if `num_worker` is 0. This can occur, for instance, in `sequential_load` mode. It's also inefficient to create a process pool for a single worker. It would be more robust to handle the sequential case (`num_worker <= 1`) separately to prevent crashes and improve efficiency.

```python
        # Use ProcessPoolExecutor for parallel loading
        max_workers = min(num_worker, len(dataset_paths))
        if max_workers > 1:
            with ProcessPoolExecutor(max_workers=max_workers) as executor:
                # Submit all loading tasks
                futures = [
                    executor.submit(_load_dataset_worker, args) for args in worker_args
                ]

                # Collect results as they complete
                for future in as_completed(futures):
                    try:
                        dataset_name, dataset, dataset_len = future.result()
                        self.datasets[dataset_name] = dataset
                        logging.info(
                            f"Loaded dataset [{dataset_name}]. "
                            f"Local dataset size: [{dataset_len}]."
                        )
                    except Exception as e:
                        raise RuntimeError(f"Failed to load dataset: {e}") from e
        else:
            # Load sequentially
            for args in worker_args:
                try:
                    dataset_name, dataset, dataset_len = _load_dataset_worker(args)
                    self.datasets[dataset_name] = dataset
                    logging.info(
                        f"Loaded dataset [{dataset_name}]. "
                        f"Local dataset size: [{dataset_len}]."
                    )
                except Exception as e:
                    raise RuntimeError(f"Failed to load dataset: {e}") from e
```

